source = '''from collections import Counter


def transform(grid):
    """Mark compartments containing at least two non-background, non-divider cells."""
    h, w = len(grid), len(grid[0])
    row_sep = [r for r in range(h) if len(set(grid[r])) == 1]
    col_sep = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    line_colors = Counter(
        [grid[r][0] for r in row_sep] + [grid[0][c] for c in col_sep]
    )
    divider = line_colors.most_common(1)[0][0]
    interior = [
        grid[r][c]
        for r in range(h)
        for c in range(w)
        if r not in row_sep and c not in col_sep
    ]
    background = Counter(interior).most_common(1)[0][0]

    row_bounds = [-1] + row_sep + [h]
    col_bounds = [-1] + col_sep + [w]
    output = [
        [background for _ in range(len(col_bounds) - 1)]
        for _ in range(len(row_bounds) - 1)
    ]
    for i, (ra, rb) in enumerate(zip(row_bounds, row_bounds[1:])):
        for j, (ca, cb) in enumerate(zip(col_bounds, col_bounds[1:])):
            count = sum(
                1
                for r in range(ra + 1, rb)
                for c in range(ca + 1, cb)
                if grid[r][c] != background and grid[r][c] != divider
            )
            if count >= 2:
                output[i][j] = 1
    return output
'''
